package gateway
import("encoding/json";"net/http";"strings";"github.com/jiejhong/GooseCab/internal/p2")
type P2API struct{Service *p2.Service}
func(a *P2API)Handler(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){p:=strings.TrimSuffix(r.URL.Path,"/");switch{case p=="/api/plans":a.plan(w,r);case p=="/api/tasks":a.task(w,r,p);case strings.HasPrefix(p,"/api/tasks/"):a.task(w,r,p);case p=="/api/capability-resolve":a.resolve(w,r);case p=="/api/blackboards":a.board(w,r);case p=="/api/private-sessions":a.session(w,r);default:next.ServeHTTP(w,r)}})}
func(a *P2API)plan(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodPost{http.NotFound(w,r);return};var v p2.Plan;if !decode(w,r,&v){return};x,e:=a.Service.CreatePlan(r.Context(),v);if e!=nil{http.Error(w,e.Error(),500);return};w.WriteHeader(201);out(w,x)}
func(a *P2API)task(w http.ResponseWriter,r *http.Request,p string){if p=="/api/tasks"&&r.Method==http.MethodPost{var v p2.Task;if !decode(w,r,&v){return};x,e:=a.Service.AddTask(r.Context(),v);if e!=nil{http.Error(w,e.Error(),500);return};w.WriteHeader(201);out(w,x);return};parts:=strings.Split(strings.TrimPrefix(p,"/api/tasks/"),"/");if len(parts)==2&&parts[1]=="retry"&&r.Method==http.MethodPost{var v struct{AgentID string `json:"agent_id"`};if !decode(w,r,&v){return};x,e:=a.Service.Retry(r.Context(),parts[0],v.AgentID);if e!=nil{http.Error(w,e.Error(),409);return};out(w,x);return};http.NotFound(w,r)}
func(a *P2API)resolve(w http.ResponseWriter,r *http.Request){out(w,a.Service.Resolve(r.URL.Query().Get("q")))}
func(a *P2API)board(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodPost{http.NotFound(w,r);return};var v p2.Blackboard;if !decode(w,r,&v){return};x,e:=a.Service.AddBoard(r.Context(),v);if e!=nil{http.Error(w,e.Error(),500);return};w.WriteHeader(201);out(w,x)}
func(a *P2API)session(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodPost{http.NotFound(w,r);return};var v p2.PrivateSession;if !decode(w,r,&v){return};x,e:=a.Service.AddSession(r.Context(),v);if e!=nil{http.Error(w,e.Error(),500);return};w.WriteHeader(201);out(w,x)}
